package cn.linkdeck.qa;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;import cn.linkdeck.adb.*;import java.io.*;import java.util.*;import org.json.*;
/** Await the actual newly-created task, rather than a transient idle flag after dialog RPC. */
public class TransferUiChecks extends RuntimeChecks {
 void completed(String name,long after)throws Exception{waitFor(name+" actual task completes",()->{JSONArray tasks=((TaskJournal)field("journal")).snapshot();for(int i=0;i<tasks.length();i++){JSONObject t=tasks.getJSONObject(i);if(t.optString("name").equals(name)&&t.optLong("created")>=after){String state=t.optString("state");if(state.equals("failed"))throw new AssertionError(t.optString("detail"));return state.equals("success");}}return false;});idle();}
 public void onStart(){Bundle result=new Bundle();try{
  getTargetContext().getSharedPreferences("linkdeck",0).edit().putBoolean("resume_connection",false).commit();
  activity=startActivitySync(new Intent().setClassName("cn.linkdeck.adb","cn.linkdeck.adb.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));
  runOnMainSync(()->{try{((EditText)field("hostInput")).setText("127.0.0.1");((EditText)field("portInput")).setText("5555");}catch(Exception e){throw new RuntimeException(e);}});tap("连接设备");waitFor("real adbd connected for transfer QA",()->client()!=null&&client().isConnected()&&!(Boolean)field("busy"));set("folder","/sdcard");call("show",new Class[]{int.class},3);idle();
  byte[] bytes=new byte[170321];for(int i=0;i<bytes.length;i++)bytes[i]=(byte)(i%251);File source=new File(getTargetContext().getCacheDir(),"audit-transfer.bin");try(OutputStream o=new FileOutputStream(source)){o.write(bytes);}long started=System.currentTimeMillis();call("onActivityResult",new Class[]{int.class,int.class,Intent.class},101,Activity.RESULT_OK,new Intent().setData(android.net.Uri.fromFile(source)));dialogTap("继续");completed("上传文件",started);
  ByteArrayOutputStream pulled=new ByteArrayOutputStream();client().pull("/sdcard/audit-transfer.bin",pulled,null);waitFor("native upload preserves all 170321 bytes",()->Arrays.equals(bytes,pulled.toByteArray()));File dest=new File(getTargetContext().getCacheDir(),"audit-downloaded.bin");set("saveRemote","/sdcard/audit-transfer.bin");started=System.currentTimeMillis();call("onActivityResult",new Class[]{int.class,int.class,Intent.class},103,Activity.RESULT_OK,new Intent().setData(android.net.Uri.fromFile(dest)));completed("下载文件",started);byte[] saved=new byte[(int)dest.length()];try(DataInputStream in=new DataInputStream(new FileInputStream(dest))){in.readFully(saved);}waitFor("native download preserves identical bytes",()->Arrays.equals(bytes,saved));client().shell("rm -f /sdcard/audit-transfer.bin").require();source.delete();dest.delete();
  File apk=new File(getTargetContext().getCacheDir(),"audit-generic.apk");try(InputStream in=getContext().getAssets().open("target.apk");OutputStream out=new FileOutputStream(apk)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}call("inspectApk",new Class[]{android.net.Uri.class},android.net.Uri.fromFile(apk));waitFor("generic APK preflight opens",()->dialogHas("安装 / 更新确认")&&dialogHas("确认更新"));started=System.currentTimeMillis();dialogTap("确认更新");completed("安装或更新电视应用",started);waitFor("generic covering install remains present in actual PackageManager",()->client().shell("pm path cn.linkdeck.qatarget").require().startsWith("package:"));call("show",new Class[]{int.class},0);tap("断开连接");result.putString("stream","TRANSFER UI QA PASSED: "+passes+" checks.\n");finish(-1,result);
 }catch(Throwable e){try{shot("audit-transfer-failure");}catch(Exception ignored){}result.putString("stream",android.util.Log.getStackTraceString(e));finish(0,result);}}
}
